#!/usr/bin/env bash
# Checks that the Odin bindings have the layout of the C API: compiles tools/abi/abi_check.c against the
# dear_bindings header and tools/abi/odin against the bindings, both generated by tools/gen, and compares
# what they print: the size and alignment of every struct and typedef, the offset of every field, and the
# value of every enum element.
#
# Usage: tools/abi/check.sh
# Needs the library (tools/build_imgui.sh or tools/fetch_imgui_libs.sh), which the Odin program links.
# Environment: CC (default: cc), ODIN (default: odin from PATH, else ~/dev/odin/Odin/odin)

set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
ODIN="${ODIN:-$(command -v odin || echo "$HOME/dev/odin/Odin/odin")}"
CC="${CC:-cc}"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

"$CC" -std=c11 -Wall -Werror \
    -I"$REPO/upstream/dear_bindings" -I"$REPO/upstream/imgui" -I"$REPO/upstream" \
    '-DIMGUI_USER_CONFIG="imconfig_odin.h"' \
    "$REPO/tools/abi/abi_check.c" -o "$TMP/abi_c"
"$TMP/abi_c" >"$TMP/c.txt"

"$ODIN" run "$REPO/tools/abi/odin" -out:"$TMP/abi_odin" >"$TMP/odin.txt"

if ! diff -u --label C "$TMP/c.txt" --label Odin "$TMP/odin.txt"; then
    echo "error: the Odin bindings do not have the layout of the C API" >&2
    exit 1
fi
echo "ABI check: $(grep -c . "$TMP/c.txt") sizes, offsets and values match"
